import json,hashlib
p='/workspace/scratch/volume4/batch309-318.json';d=json.load(open(p))
def page(n,rows):
 ps=[]
 for i,(ar,ru) in enumerate(rows,1):
  sid=f'v4-p{n}-{i:02}';ps.append(dict(id=sid,ar=ar,sha256=hashlib.sha256(ar.encode()).hexdigest(),witness='uploaded_2019_control_pdf',source_complete=True))
  d['units'].append(dict(id=sid+'-ru',source_ids=[sid],printed_pages=[n],ar=ar,ru=ru,draft_status='draft',print_collation='control_image_read',independent_human_review=False))
 d['pages'].append(dict(printed_page=n,pdf_leaf=n,witness_status='control_print_visually_read',publisher_footnote_text_imported=False,paragraphs=ps))
page(309,[
('وكل سليم العقل والفطرة يعرف قدر الصانع وحذقه، وتبريزه على غيره، وتفرده بكمال لم يشاركه فيه غيره = من مشاهدة صنعه، فكيف لا تعرف صفات من هذا العالم العلوي والسفلي وهذه المخلوقات من بعض صنعه؟!', 'Всякий, чей разум и естество здравы, узнаёт о достоинстве мастера, его искусности, превосходстве над другими и единственном в своём роде совершенстве, которого с ним никто не разделяет, наблюдая за его изделием. Как же не познать качества Того, для Кого этот высший и низший мир и все эти творения — лишь часть Его творения?!'),
('وإذا اعتبرت المخلوقات والمأمورات، وجدتها كلها دالة على النعوت والصفات وحقائق الأسماء الحسنى، وعلمت أن المعطل من أعظم الناس عمى ومكابرة. ويكفي ظهور شاهد الصنع فيك خاصة كما قال تعالى: {وفي أنفسكم أفلا تبصرون} [الذاريات: ٢١]، فالموجودات بأسرها شواهد صفات الرب ـ جل جلاله ـ ونعوته وأسمائه، فهي كلها تشير إلى الأسماء الحسنى وحقائقها، وتنادي عليها، وتدل عليها، وتخبر بها بلسان النطق والحال، كما قيل:', 'Если ты вникнешь в сотворённое и предписанное, то обнаружишь, что всё оно указывает на свойства, качества и реальности прекрасных имён. Ты поймёшь, что отрицающий качества — один из самых слепых и упорствующих людей. Достаточно уже того, как свидетельство о творении обнаруживается в тебе самом. Всевышний сказал: {وفي أنفسكم أفلا تبصرون} — «И в вас самих. Неужели вы не видите?» [51:21]. Всё существующее свидетельствует о качествах, свойствах и именах Господа, велико Его величие. Всё это указывает на прекрасные имена и их реальности, возвещает о них, свидетельствует о них и сообщает о них языком речи и состояния. Как сказано:'),
('تأمل سطور الكائنات فإنها من الملك الأعلى إليك رسائل\nوقد خط فيها لو تأملت خطها «ألا كل شيء ما خلا الله باطل»\nتشير بإثبات الصفات لربها فصامتها يهدي ومن هو قائل', 'Вчитайся в строки творений: они — послания тебе от Высшего Царя.\nВ них начертано, если вглядеться в их письмена: «Поистине, всё, кроме Аллаха, тщетно».\nОни указывают на утверждение качеств своего Господа: ведут и безмолвные среди них, и говорящие.')])
page(310,[
('فلست ترى شيئا أدل على شيء من دلالة المخلوقات على صفات خالقها، ونعوت كماله، وحقائق أسمائه، وقد تنوعت أدلتها بحسب تنوعها، فهي تدل عقلا وحسا وفطرة ونظرا واعتبارا.', 'Ты не найдёшь более явного указания одной вещи на другую, чем указание творений на качества их Творца, свойства Его совершенства и реальности Его имён. Их свидетельства разнообразны сообразно разнообразию самих творений: они указывают посредством разума, чувств, естества, рассмотрения и назидательного размышления.'),
('قوله: «بتبصير النور القائم في السر»، يعني: أن النور الإلهي الذي يجعله الله لعبده، ويلقيه عليه، ويودعه في سره، هو الذي يبصره بشواهد صفاته. فكلما قوي هذا النور في قلب العبد كان بصره بالصفات أتم وأكمل، وكلما قل نصيبه من هذا النور وطفئ مصباحه في قلبه طفئ نور التصديق بالصفات وإثباتها في قلبه، فإنه إنما يشاهدها بذلك النور، فإذا فقده لم يشاهدها، وجاءت الشبه الباطلة مع تلك الظلمة، فلم يكن له نصيب منها سوى الإنكار.', 'Его слова «благодаря тому, что даёт прозреть свет, пребывающий в сокровенной глубине» означают: божественный свет, который Аллах дарует Своему рабу, ниспосылает ему и влагает в его сокровенную глубину, позволяет ему увидеть свидетельства Его качеств. Чем сильнее этот свет в сердце раба, тем полнее и совершеннее его видение качеств. Чем меньше его доля этого света и чем сильнее угасает светильник в его сердце, тем сильнее угасает в сердце свет признания качеств и их утверждения. Ведь он созерцает их именно благодаря этому свету. Утратив его, он перестаёт их созерцать; к этой тьме присоединяются ложные сомнения, и единственным его уделом в отношении качеств становится отрицание.'),
('قوله: «وطيب حياة العقل لزرع الفكر»، أي: يدرك الصفات بذلك النور القائم في سره، وطيب حياة عقله، التي طيبها زرع الفكر الصحيح المتعلق بما دعا الله سبحانه إلى الفكر فيه بقوله: {ويتفكرون في خلق السماوات والأرض} [آل عمران: ١٩١]. وقوله: {أولم يتفكروا في أنفسهم ما خلق الله السماوات والأرض وما بينهما إلا بالحق} [الروم: ٨]. وقوله: {كذلك يبين الله لكم الآيات لعلكم تتفكرون في الدنيا والآخرة} [البقرة: ٢١٩ ـ ٢٢٠]،', 'Его слова «и благой жизнью разума благодаря посеву мысли» означают, что он постигает качества благодаря этому свету в своей сокровенной глубине и благой жизни разума, которую сделал благой посев верной мысли о том, над чем Пречистый Аллах призвал размышлять. Он сказал: {ويتفكرون في خلق السماوات والأرض} — «И размышляют о сотворении небес и земли» [3:191]; {أولم يتفكروا في أنفسهم ما خلق الله السماوات والأرض وما بينهما إلا بالحق} — «Неужели они не размышляли о самих себе? Аллах сотворил небеса, землю и то, что между ними, только по истине» [30:8]; {كذلك يبين الله لكم الآيات لعلكم تتفكرون في الدنيا والآخرة} — «Так Аллах разъясняет вам знамения, чтобы вы размышляли о земной и Последней жизни» [2:219–220].')])
page(311,[
('فيتفكرون في الآيات التي يبينها لهم، فيستدلون بها على توحيده، وصفات كماله، وصدق رسله، والعلم بلقائه، ويتفكرون في الدنيا وانقضائها واضمحلالها ودناءتها، والآخرة ودوامها وبقائها وشرفها. وقوله: {ومن آياته أن خلق لكم من أنفسكم أزواجا لتسكنوا إليها وجعل بينكم مودة ورحمة إن في ذلك لآيات لقوم يتفكرون} [الروم: ٢١].', 'Они размышляют о знамениях, которые Он им разъясняет, и на их основании заключают о Его единственности, качествах Его совершенства, правдивости Его посланников и обретают знание о встрече с Ним. Они размышляют о земной жизни, её окончании, исчезновении и низости, а также о Последней жизни, её непрерывности, вечности и величии. И Его слова: {ومن آياته أن خلق لكم من أنفسكم أزواجا لتسكنوا إليها وجعل بينكم مودة ورحمة إن في ذلك لآيات لقوم يتفكرون} — «Среди Его знамений — то, что Он сотворил для вас из вас самих супруг, чтобы вы находили в них покой, и установил между вами любовь и милость. Поистине, в этом — знамения для людей размышляющих» [30:21].'),
('فالفكر الصحيح المؤيد بحياة القلب ونور البصيرة يدل على إثبات صفات الكمال ونعوت الجلال. وأما فكر مصحوب بموت القلب وعمى البصيرة، فإنما يعطى صاحبه نفيها وتعطيلها.', 'Верная мысль, подкреплённая жизнью сердца и светом духовной зоркости, ведёт к утверждению качеств совершенства и свойств величия. Мысль же, сопровождаемая смертью сердца и слепотой духовной зоркости, даёт своему обладателю лишь отрицание этих качеств и лишение Господа их.'),
('قوله: «وحياة القلب بحسن النظر بين التعظيم وحسن الاعتبار»، يعني: أنه يضاف إلى نور البصيرة وطيب حياة العقل: حياة القلب بحسن النظر الدائر بين تعظيم الخالق ـ جل جلاله ـ وحسن الاعتبار بمصنوعاته الدالة عليه، فلا بد من الأمرين، فإنه إن غفل بالتعظيم عن حسن الاعتبار لم يحصل له الاستدلال على الصفات، وإن حصل له الاعتبار من غير تعظيم للخالق سبحانه لم يستفد به إثبات الصفات، فإذا اجتمع له تعظيم الخالق وحسن النظر في صنعه أثمر له إثبات صفات كماله ولا بد.', 'Его слова «и жизнью сердца благодаря верному рассмотрению между возвеличиванием и благим назидательным размышлением» означают: к свету духовной зоркости и благой жизни разума присоединяется жизнь сердца посредством верного рассмотрения, обращённого к возвеличиванию Творца, велико Его величие, и к благому назидательному размышлению о Его творениях, указывающих на Него. Необходимы обе стороны. Если, занявшись возвеличиванием, человек оставит назидательное размышление, он не обретёт доказательства качеств. Если же станет размышлять, не возвеличивая Пречистого Творца, это не приведёт его к утверждению качеств. Когда же в нём соединятся возвеличивание Творца и верное рассмотрение Его творения, они непременно принесут плод — утверждение качеств Его совершенства.'),
('و«الاعتبار» هو أن يعبر نظره من الأثر إلى المؤثر، ومن الصنعة إلى', 'Назидательное размышление состоит в том, чтобы взгляд переходил от следа к Тому, Кто его оставил, от изделия — к')])
page(312,[
('الصانع، ومن الدليل إلى المدلول، فينتقل إليه بسرعة ولطف إدراك، فينتقل ذهنه من الملزوم إلى لازمه. قال تعالى: {فاعتبروا يا أولي الأبصار} [الحشر: ٢]. و«الاعتبار» افتعال من العبور، وهو عبور القلب من الملزوم إلى لازمه، ومن النظير إلى نظيره.', 'Мастеру, от доказательства — к доказываемому, переходя быстро и с тонкостью постижения: ум переходит от того, что необходимо влечёт за собой нечто, к его необходимому следствию. Всевышний сказал: {فاعتبروا يا أولي الأبصار} — «Извлеките же урок, обладающие зрением!» [59:2]. Слово «и‘тибар» образовано от «‘убур» — переход; это переход сердца от того, что необходимо влечёт за собой нечто, к его необходимому следствию и от одного подобного — к другому.'),
('وهذا الاعتبار يضعف ويقوى، حتى يستدل صاحبه بصفات الرب تعالى وكماله على ما يفعله، لحسن اعتباره وصحة نظره. وهذا اعتبار الخواص واستدلالهم، فإنهم يستدلون بالله وأسمائه وصفاته على أفعاله، وأنه يفعل كذا ولا يفعل كذا، فيفعل ما هو موجب حكمته وعلمه وغناه وحمده، ولا يفعل ما يناقض ذلك.', 'Это назидательное размышление бывает слабее и сильнее, вплоть до того, что человек благодаря благому размышлению и верному рассмотрению заключает о деяниях Всевышнего Господа на основании Его качеств и совершенства. Таковы размышление и доказательство избранных: они заключают по Аллаху, Его именам и качествам о Его деяниях, о том, что Он совершает одно и не совершает другого. Он совершает то, что обусловлено Его мудростью, знанием, самодостаточностью и достохвальностью, и не совершает того, что этому противоречит.'),
('وقد ذكر سبحانه هذين الطريقين في كتابه، فقال في الطريق الأولى: {سنريهم آياتنا في الآفاق وفي أنفسهم حتى يتبين لهم أنه الحق}، ثم قال في الطريق الثانية: {أولم يكف بربك أنه على كل شيء شهيد} [فصلت: ٥٣]، فمخلوقاته دالة على ذاته وأسمائه وصفاته، وأسماؤه وصفاته دالة على ما يفعله ويأمر به، وما لا يفعله ولا يأمر به.', 'Пречистый упомянул оба пути в Своей Книге. О первом Он сказал: {سنريهم آياتنا في الآفاق وفي أنفسهم حتى يتبين لهم أنه الحق} — «Мы покажем им Наши знамения по краям земли и в них самих, пока им не станет ясно, что это — истина». Затем о втором пути: {أولم يكف بربك أنه على كل شيء شهيد} — «Разве недостаточно того, что твой Господь — Свидетель всякой вещи?» [41:53]. Его творения указывают на Его Сущность, имена и качества, а Его имена и качества указывают на то, что Он совершает и повелевает, а также на то, чего Он не совершает и не повелевает.'),
('مثال ذلك: أن اسمه «الحميد» ـ سبحانه ـ يدل على أنه لا يأمر بالفحشاء والمنكر، واسمه «الحكيم» يدل على أنه لا يخلق شيئا عبثا، واسمه «الغني» يدل على أنه لم يتخذ صاحبة ولا ولدا، واسمه «الملك» يدل على ما يستلزم حقيقة ملكه من: قدرته، وتدبيره، وعطائه ومنعه، وثوابه وعقابه، وبث رسله في أقطار مملكته، وإعلام عبيده بمراسيمه وعهوده إليهم، واستوائه على', 'Например, Его имя «Достохвальный», пречист Он, указывает на то, что Он не повелевает мерзость и порицаемое. Его имя «Мудрый» указывает на то, что Он не творит ничего напрасно. Его имя «Самодостаточный» указывает на то, что Он не взял ни супруги, ни сына. Его имя «Царь» указывает на то, что необходимо следует из истинности Его царствования: Его могущество, управление, дарование и удержание, воздаяние и наказание, направление посланников во все пределы Его царства, доведение до рабов Его установлений и заветов, а также Его возвышение над')])
json.dump(d,open(p,'w'),ensure_ascii=False,indent=2)
